function sanRoadSeeds445(rootIdx){
  const out=[];if(rootIdx<0||rootIdx>=N*N)return out;const b=tiles[rootIdx]&&tiles[rootIdx].bld;if(!b||b.ref)return out;
  const rx=rootIdx%N,ry=(rootIdx/N)|0,sz=Math.max(1,b.sz||1);
  for(let fy=0;fy<sz;fy++)for(let fx=0;fx<sz;fx++)for(const[dx,dy]of DIRV){
    const nx=rx+fx+dx,ny=ry+fy+dy;if(!inMap(nx,ny))continue;const j=idx(nx,ny);if(!tiles[j].road||out.includes(j))continue;out.push(j);
  }
  return out;
}

text.sanAccessRoot445:
function sanAccessRoot445(rootIdx){
  ensureSan445();if(rootIdx<0||rootIdx>=N*N)return {road:-1,dist:SAN_INF445,src:-1};
  const b=tiles[rootIdx]&&tiles[rootIdx].bld;if(!b)return {road:-1,dist:SAN_INF445,src:-1};
  if(b.ref)rootIdx=idx(b.ref[0],b.ref[1]);
  const roads=sanRoadSeeds445(rootIdx);let best=-1,bd=SAN_INF445,bs=-1;
  for(const j of roads){const d=SAN_DIST445[j];if(d<bd){best=j;bd=d;bs=SAN_SRC445[j];}}
  return {road:best,dist:bd,src:bs};
}

text.computeSanitation445:
function computeSanitation445(){
  ensureSan445();SAN_DIST445.fill(SAN_INF445);SAN_SRC445.fill(-1);SAN_ACTIVE445.fill(0);sanActiveRoots445.length=0;sanAllRoots445.length=0;
  let totalCap=0,activeCap=0,totalFacilities=0,activeFacilities=0,head=0,tail=0;const activeByK={};
  // 先把所有「真的接到道路」的處理設施作為多源 BFS 種子。多格設施任何 footprint 邊都可接路。
  for(let i=0;i<N*N;i++){
    const b=tiles[i].bld;if(!b||b.ref||!isSanFacility445(b.k))continue;
    totalFacilities++;totalCap+=SAN_CAP445[b.k];sanAllRoots445.push(i);
    const seeds=sanRoadSeeds445(i);if(!seeds.length)continue;
    SAN_ACTIVE445[i]=1;activeFacilities++;activeCap+=SAN_CAP445[b.k];activeByK[b.k]=(activeByK[b.k]||0)+1;sanActiveRoots445.push(i);
    for(const j of seeds)if(SAN_DIST445[j]!==0){SAN_DIST445[j]=0;SAN_SRC445[j]=i;sanQ445[tail++]=j;}
  }
  while(head<tail){
    const cur=sanQ445[head++],d=SAN_DIST445[cur],src=SAN_SRC445[cur],cx=cur%N,cy=(cur/N)|0;
    for(const[dx,dy]of DIRV){const nx=cx+dx,ny=cy+dy;if(!inMap(nx,ny))continue;const j=idx(nx,ny);if(!tiles[j].road)continue;const nd=d+1;if(nd<SAN_DIST445[j]){SAN_DIST445[j]=nd;SAN_SRC445[j]=src;sanQ445[tail++]=j;}}
  }
  let totalClients=0,reachedClients=0,unservedClients=0,longClients=0;
  for(let i=0;i<N*N;i++){
    const b=tiles[i].bld;if(!b||b.ref||!isSanClient445(b.k))continue;totalClients++;const a=sanAccessRoot445(i);
    if(a.dist<SAN_INF445){reachedClients++;if(a.dist>SAN_LONG_DIST445)longClients++;}else unservedClients++;
  }
  const formal=pop>=SAN_FORMAL_POP445&&!window.__legacySanitation445,effectiveCap=formal?activeCap:totalCap; // T445 rollback：__legacySanitation445=true ⇒ 模擬語義退回 T444（全容量＋舊 T119 距離）
  sanStat445={formal,totalCap,activeCap,effectiveCap,totalFacilities,activeFacilities,offlineFacilities:totalFacilities-activeFacilities,totalClients,reachedClients,unservedClients,longClients,activeByK};
  sanDirty445=false;window.__t445Sanitation={...sanStat445,activeByK:{...activeByK}};
  if(!sanitationLegacy452())rebuildSanitationDistricts452(); // T452：T445 reachability 完成後，沿同一份 road/active facility 快照建立 local capacity ownership
  return sanStat445;
}

text.rebuildSanitationDistricts452:
function rebuildSanitationDistricts452(){
  ensureSan452();SAN_NET452.fill(-1);SAN_PARENT452.fill(-1);SAN_RANK452.fill(0);sanDistricts452=[];sanFacilityMap452=new Map();sanRootAlloc452=new Map();sanAlloc452=emptySanAlloc452();
  // A. 每條道路先成為 union-find node，四鄰道路合併。
  for(let i=0;i<N*N;i++)if(tiles[i].road)SAN_PARENT452[i]=i;
  for(let y=0;y<N;y++)for(let x=0;x<N;x++){const i=idx(x,y);if(SAN_PARENT452[i]<0)continue;if(x+1<N&&SAN_PARENT452[i+1]>=0)sanUnion452(i,i+1);if(y+1<N&&SAN_PARENT452[i+N]>=0)sanUnion452(i,i+N);}
  // B. 處理設施是場內動線節點：完整 footprint frontage 若貼多段道路，容量共用同一個 sanitation district。
  for(const root of sanAllRoots445){const b=tiles[root]&&tiles[root].bld;if(!b||b.ref||!isSanFacility445(b.k))continue;const f=sanFacilityFrontage452(root);for(let k=1;k<f.length;k++)sanUnion452(f[0],f[k]);}
  // C. compact 全道路 component；即便沒有處理廠也保留 district，讓「死路網」可被診斷/修復。
  const rootToDist=new Map();
  for(let i=0;i<N*N;i++)if(SAN_PARENT452[i]>=0){const r=sanFind452(i);let d=rootToDist.get(r);if(d===undefined){d=sanDistricts452.length;rootToDist.set(r,d);sanDistricts452.push({id:d,roads:0,anchor:i,facilities:0,capacity:0,demand:0,spare:0,overflow:0,load:0,clients:0,byK:{},samples:[]});}SAN_NET452[i]=d;const q=sanDistricts452[d];q.roads++;if(q.samples.length<96)q.samples.push(i);}
  let nominal=0,online=0,onlineFacilities=0,offlineFacilities=0;
  for(const root of sanAllRoots445){const b=tiles[root]&&tiles[root].bld;if(!b||b.ref||!isSanFacility445(b.k))continue;const baseCap=SAN_CAP445[b.k]||0,cap=baseCap*assetAvailability493(root,'sanitation');nominal+=baseCap;const f=sanRoadSeeds445(root).filter(j=>SAN_NET452[j]>=0),on=!!SAN_ACTIVE445[root]&&f.length>0&&cap>.01,d=on?SAN_NET452[f[0]]:-1;const info={root,k:b.k,capacity:cap,nominalCapacity:baseCap,online:on,district:d};sanFacilityMap452.set(root,info);if(on&&d>=0&&sanDistricts452[d]){const q=sanDistricts452[d];q.capacity+=cap;q.facilities++;q.byK[b.k]=(q.byK[b.k]||0)+1;online+=cap;onlineFacilities++;}else offlineFacilities++;}
  window.__t452Sanitation={nominalCapacity:nominal,onlineCapacity:online,offlineCapacity:nominal-online,districts:sanDistricts452.length,onlineFacilities,offlineFacilities,formal:!!sanStat445.formal};return window.__t452Sanitation;
}

text.sanRootDistrictChoice452:
function sanRootDistrictChoice452(rootIdx){
  ensureSanitationDistricts452();const roads=sanRoadSeeds445(rootIdx);if(!roads.length)return {district:-1,road:-1,dist:SAN_INF445,src:-1};
  const cand=[];for(const j of roads){const d=SAN_NET452[j];if(d<0)continue;cand.push({district:d,road:j,dist:SAN_DIST445[j],src:SAN_SRC445[j]});}
  if(!cand.length)return {district:-1,road:-1,dist:SAN_INF445,src:-1};cand.sort((a,b)=>a.dist-b.dist||a.district-b.district||a.road-b.road);return cand[0];
}

text.sanWasteOfRoot452:
function sanWasteOfRoot452(rootIdx,recycleMul){
  const b=tiles[rootIdx]&&tiles[rootIdx].bld;if(!b||b.ref)return 0;recycleMul=Number.isFinite(recycleMul)?recycleMul:1;let w=0;
  if(b.k===1||b.k===127||b.k===33||b.k===105)w=residentPopulation488(rootIdx,b)*.05;
  else if(b.k===3&&b.pw)w=enterpriseActualJobs489(rootIdx,b,'employed')*.08;
  return w*recycleMul;
}

text.prepareSanitationLoad452:
function prepareSanitationLoad452(recycleMul){
  ensureSanitationDistricts452();sanRootAlloc452=new Map();const a=emptySanAlloc452();a.prepared=true;
  for(const q of sanDistricts452){q.demand=0;q.spare=q.capacity;q.overflow=0;q.load=0;q.clients=0;}
  for(let i=0;i<N*N;i++){const b=tiles[i].bld;if(!b||b.ref)continue;const demand=sanWasteOfRoot452(i,recycleMul);if(demand<=0)continue;a.totalDemand+=demand;const pick=sanRootDistrictChoice452(i);if(pick.district<0){a.noRoadDemand+=demand;sanRootAlloc452.set(i,{...pick,demand,reason:'no-road'});continue;}const q=sanDistricts452[pick.district];q.demand+=demand;q.clients++;a.assignedDemand+=demand;if(q.capacity<=0||pick.dist>=SAN_INF445)a.deadDemand+=demand;sanRootAlloc452.set(i,{...pick,demand,reason:q.capacity<=0||pick.dist>=SAN_INF445?'dead-network':'ok'});}
  let worst=-1,worstLoad=0,overflow=0,overN=0;for(const q of sanDistricts452){q.spare=Math.max(0,q.capacity-q.demand);q.overflow=Math.max(0,q.demand-q.capacity);q.load=q.capacity>0?q.demand/q.capacity:(q.demand>0?Infinity:0);overflow+=q.overflow;if(q.capacity>0&&q.demand>q.capacity+1e-9){overN++;if(q.load>worstLoad){worstLoad=q.load;worst=q.id;}}}
  a.overflow=overflow;a.overloadedDistricts=overN;a.worstDistrict=worst;a.worstLoad=worstLoad;sanAlloc452=a;window.__t452Load={...a};return a;
}

