  if(tiles[i].road){const d=SAN_NET452[i],q=d>=0?sanDistricts452[d]:null,dd=SAN_DIST445[i],src=SAN_SRC445[i];return {kind:'road',district:d,capacity:q?q.capacity:0,demand:q?q.demand:0,spare:q?q.spare:0,overflow:q?q.overflow:0,load:q?q.load:0,reachable:dd<SAN_INF445,dist:dd,src,sourceText:dd<SAN_INF445?sanitationSourceText445(src):'無'};}
  if(b&&isSanFacility445(b.k)){const f=sanFacilityMap452.get(i),q=f&&f.district>=0?sanDistricts452[f.district]:null;return {kind:'facility',facility:true,active:!!(f&&f.online),district:f?f.district:-1,cap:f?f.capacity:(SAN_CAP445[b.k]||0),capacity:q?q.capacity:0,demand:q?q.demand:0,spare:q?q.spare:0,overflow:q?q.overflow:0,load:q?q.load:0};}
