text.computeGarbLocal:
function computeGarbLocal(){
  let far409=0,unserved445=0,warn445=0;
  if(!sanStat445.formal){
    const dsrc=[];
    for(let i=0;i<N*N;i++){const b=tiles[i].bld;if(b&&((!b.ref&&b.k===8)||b.k===62))dsrc.push(i);}
    const dist=new Uint16Array(N*N).fill(9999),q=[];
    for(const di of dsrc){const dx0=di%N,dy0=(di/N)|0;for(const[dx,dy]of DIRV){const nx=dx0+dx,ny=dy0+dy;if(inMap(nx,ny)){const j=idx(nx,ny);if(T(j).road&&dist[j]>0){dist[j]=0;q.push(j);}}}}
    let head=0;while(head<q.length){const cur=q[head++],d=dist[cur],cx=cur%N,cy=(cur/N)|0;for(const[dx,dy]of DIRV){const nx=cx+dx,ny=cy+dy;if(!inMap(nx,ny))continue;const j=idx(nx,ny);if(T(j).road&&dist[j]>d+1){dist[j]=d+1;q.push(j);}}}
    for(let i=0;i<N*N;i++){const b=tiles[i].bld;if(!b||b.k!==1){garbLocal[i]=0;continue;}const x=i%N,y=(i/N)|0;let bd=9999;for(const[dx,dy]of DIRV){const nx=x+dx,ny=y+dy;if(inMap(nx,ny)){const j=idx(nx,ny);if(T(j).road)bd=Math.min(bd,dist[j]);}}if(bd>18){garbLocal[i]=clamp(garbRatio+.3,0,2);b.h=clamp(b.h-.045,.05,1);far409++;}else garbLocal[i]=garbRatio;}
    return {far:far409,unserved:0,warn:0,penAvg:0};
  }
  if(sanitationLegacy452()){ // T452 rollback：逐字保留 T445 正式清運＝全城 ratio + 局部 reach
    for(let i=0;i<N*N;i++){const b=tiles[i].bld;if(!b||b.k!==1){garbLocal[i]=0;continue;}const a=sanAccessRoot445(i);if(a.dist>=SAN_INF445){garbLocal[i]=clamp(garbRatio+.45,0,2);b.h=clamp(b.h-.06,.05,1);unserved445++;}else if(a.dist>SAN_LONG_DIST445){garbLocal[i]=clamp(garbRatio+.3,0,2);b.h=clamp(b.h-.045,.05,1);far409++;}else{garbLocal[i]=garbRatio;if(a.dist>SAN_WARN_DIST445)warn445++;}}
    return {far:far409,unserved:unserved445,warn:warn445,penAvg:0};
  }
  if(!sanAlloc452.prepared)prepareSanitationLoad452(pol&&pol.recycle?.85:1);
  let capPenSum=0,capPenN=0;
  for(let i=0;i<N*N;i++){
    const b=tiles[i].bld;if(!b||b.k!==1){garbLocal[i]=0;continue;}const st=sanitationAt452(i%N,(i/N)|0),q=st&&st.district>=0?sanDistricts452[st.district]:null;
    if(!st||st.district<0||!q||q.capacity<=0||st.dist>=SAN_INF445){garbLocal[i]=2;b.h=clamp(b.h-.06,.05,1);unserved445++;continue;}
    const localRatio=clamp(q.load,0,2),capPen=q.load>1?(q.load-1)*.15:0;if(capPen>0){b.h=clamp(b.h-capPen,.05,1);capPenSum+=capPen;capPenN++;}
    if(st.dist>SAN_LONG_DIST445){garbLocal[i]=clamp(localRatio+.3,0,2);b.h=clamp(b.h-.045,.05,1);far409++;}
    else{garbLocal[i]=localRatio;if(st.dist>SAN_WARN_DIST445)warn445++;}
  }
  return {far:far409,unserved:unserved445,warn:warn445,penAvg:capPenN?capPenSum/capPenN:0};
}

